WFJ.Data.add("spell", {
  [440014] = { nil, "$D1ごとに$N1のFireダメージを受けます。", nil, 0xe0649799, "mu" },
  [440054] = { "影の悪鬼を生み出して対象を攻撃させます。Shadowfiendが攻撃すると、術者はマナを$N1%得ます。$D1持続します。", nil, 0x609469be, nil, "um" },
  [440072] = { nil, "幽霊になったような気分です。", nil, 0xfcf0fb0b, "mu" },
  [440108] = { nil, "攻撃も呪文の使用もできません。", nil, 0x3f987751, "mu" },
  [440113] = { "近接攻撃の命中に$N1%の確率でSudden Deathを得る効果があります。Sudden Deathにより、対象の体力の状態に関係なくExecuteを一度使用できます。Sudden DeathでExecuteが使用可能になった場合、Executeを使用した後も怒りが$N2残ります。", nil, 0x06740070, nil, "um" },
  [440114] = { nil, "目標の体力に関係なくExecuteを一度使用でき、使用後に怒りが$N1残ります。", nil, 0x0287cac8, "mu" },
  [440212] = { { "半径$N2ヤードに$N1のFrostダメージを与えます。", shape = { "2/0" } }, nil, 0x477a9729, nil, "um" },
  [440213] = { nil, "Blood Loaが望むのは勝負であり、無力な者の虐殺ではない！レイドグループを抜けなければ、その怒りを受けることになります！すべての能力値と移動速度が$N1%低下します。", nil, 0xa7fb784d, "mu" },
  [440236] = { "Hypnotic Bladeに使用して、強力な武器を作り出します。", nil, 0x0c3b5db4, nil, "um" },
  [440285] = { nil, "次のChain Lightning、Chain Heal、Lava Burstの呪文が即時詠唱になります。", nil, 0x72a3c338, "mu" },
  [440471] = { nil, "$D1ごとに$N1のNatureダメージを受けます。", nil, 0x508bfddc, "mu" },
  [440483] = { nil, "与える物理ダメージが$N1%増加します。", nil, 0x07715b9c, "mu" },
  [440484] = { "Bloodthirst、Mortal Strike、Shield Slamで対象にダメージを与えると、初回は100%、それ以降は毎回$N2%の確率で自分がEnraged状態になり（Enraged状態が必要なアビリティが使用可能になります）、$D1の間、与えるPhysicalダメージが$N3%増加します。", nil, 0x50d6447a, nil, "um" },
  [440488] = { "ウォリアーの前方に衝撃波を放ち、前方扇状の$N2ヤード以内にいるすべての敵に$N1のダメージを与え、$D1スタンさせます。", "スタンしています。", 0x6860b6dd, 0x27f95286, "uu" },
  [440492] = { "外套にFresh Meatのルーンを刻みます：\n\n$I1\nBloodthirst、Mortal Strike、Shield Slamで対象にダメージを与えると、初回は100%、以降は毎回$N2%の確率でEnrage状態になり（Enraged状態が必要なアビリティが使用可能になります）、$D1の間、与えるPhysicalダメージが$N3%増加します。", nil, 0x5a6bf051, nil, "um" },
  [440493] = { "Fresh Meatのアビリティを得ます：\n\n$I1\nBloodthirst、Mortal Strike、Shield Slamで対象にダメージを与えると、初回は100%、それ以降は毎回$N2%の確率で自分がEnraged状態になり（Enraged状態が必要なアビリティが使用可能になります）、$D1の間、与えるPhysicalダメージが$N3%増加します。", nil, 0x1c9eb8f1, nil, "um" },
  [440494] = { "外套にSudden Deathのルーンを刻みます：\n\n$I1\n近接攻撃が命中すると、$N1%の確率でSudden Deathを得ます。Sudden Deathにより、対象の体力の状態に関係なくExecuteを一回使用できます。Sudden DeathによってExecuteが使用可能になった場合、Execute使用後に怒りが$N2残ります。", nil, 0x6d800699, nil, "um" },
  [440495] = { "Fresh Meatのアビリティを得ます：\n\n$I1\n近接攻撃の命中に$N1%の確率でSudden Deathを得る効果があります。Sudden Deathにより、対象の体力の状態に関係なくExecuteを一度使用できます。Sudden DeathでExecuteが使用可能になった場合、Executeを使用した後も怒りが$N2残ります。", nil, 0xc8902296, nil, "um" },
  [440496] = { "外套にShockwaveのルーンを刻みます：\n\n$I1\nウォリアーの前方に衝撃波を放ち、$N1のダメージを与え、前方の円錐範囲$N2ヤード以内のすべての敵を$D1の間スタンさせます。", nil, 0x56e19117, nil, "um" },
  [440497] = { "Shockwaveのアビリティを得ます：\n\n$I1\nウォリアーの前方に衝撃波を放ち、前方の円錐範囲$N2ヤード以内にいるすべての敵の対象に$N1のダメージを与え、$D1の間スタンさせます。", nil, 0x077d7403, nil, "um" },
  [440505] = { "$D1の間、服用者を透明にします。", "Invisibility", 0x3fdd20e3, 0x757e6c9b, "uu" },
  [440520] = { "Volleyのマナコストを$N1%減少させ、クールダウンを$N2%短縮し、ダメージを$N3%増加させ、ダメージを伴う攻撃で詠唱が遅延しなくなります。さらに、Volleyはダメージを与えるたびに、遠隔のAttack Powerの$N4%を追加ダメージとして与えます。", nil, 0xe55f42f9, nil, "um" },
  [440529] = { "Trapのアビリティと近接アビリティのマナコストを$N1%減少させます。さらに、クリティカルヒット時に$N2%の確率で、$D1の間、詠唱中もマナの回復の$N3%が続くようになります。", nil, 0xbc56e52f, nil, "um" },
  [440531] = { nil, "移動速度が$N1%上昇します", nil, 0xda8c3de1, "mu" },
  [440533] = { "Raptor Strikeを使用した後、$D1の間、移動速度が$N1%上昇します。\n\nペットのダメージアビリティが対象をRabid Frenzy状態にし、$D2の間、近接攻撃力を$N3上昇させますが、アーマーを$N4低下させます。Rabid状態の敵は逃げず、FearとHorrorの効果を無視します。", nil, 0xd8584ed2, nil, "um" },
  [440557] = { "外套にResourcefulnessのルーンを刻みます：\n\n$I1\nTrapアビリティと近接アビリティのマナコストを$N1%減少させます。さらに、クリティカルは$N2%の確率で、$D1の間、詠唱中もマナの回復の$N3%が継続するようにします。", nil, 0x5c9e589a, nil, "um" },
  [440558] = { "Resourcefulnessのアビリティを得ます：\n\n$I1\nTrapのアビリティと近接アビリティのマナコストを$N1%減少させます。さらに、クリティカルには$N2%の確率で、$D1の間、詠唱中もマナ回復の$N3%を継続させる効果があります。", nil, 0x05ed64c8, nil, "um" },
  [440560] = { "外套にImproved Volleyのルーンを刻みます：\n\n$I1\nVolleyのマナコストを$N1%減少させ、クールダウンを$N2%短縮し、ダメージを$N3%増加させ、ダメージ攻撃による詠唱の遅延を受けなくなります。さらに、Volleyはダメージを与えるたびに、遠隔Attack Powerの$N4%を追加ダメージとして与えます。", nil, 0x20ba9081, nil, "um" },
  [440561] = { "Improved Volleyのアビリティを得ます：\n\n$I1\nVolleyのマナコストを$N1%減少させ、クールダウンを$N2%短縮し、ダメージを$N3%増加させ、ダメージを伴う攻撃で詠唱が遅延しなくなります。さらに、Volleyはダメージを与えるたびに、遠隔のAttack Powerの$N4%を追加ダメージとして与えます。", nil, 0x15236ce6, nil, "um" },
  [440563] = { "外套にHit and Runのルーンを刻みます：\n\n$I1\nRaptor Strike使用後、$D1の間、移動速度が$N1%上昇します。\n\nペットのダメージ系アビリティは対象をRabid Frenzy状態にし、$D2の間、その近接攻撃力を$N3上昇させますが、アーマーを$N4減少させます。Rabid状態の敵は逃走せず、FearとHorrorの効果を無視します。", nil, 0x15040a9f, nil, "um" },
  [440564] = { "Hit and Runのアビリティを得ます：\n\n$I1\nRaptor Strikeを使用した後、$D1の間、移動速度が$N1%上昇します。\n\nペットのダメージアビリティが対象をRabid Frenzy状態にし、$D2の間、近接攻撃力を$N3上昇させますが、アーマーを$N4低下させます。Rabid状態の敵は逃げず、FearとHorrorの効果を無視します。", nil, 0xa00297a6, nil, "um" },
  [440569] = { "Chain Lightningのクールダウンを$N1%短縮し、Earthbind Totemの設置時に対象を$D1の間その場に縛り付け、Flame Shockの継続ダメージを$N3%増加させます。", nil, 0x92749d84, nil, "um" },
  [440574] = { nil, "根を張られています。", nil, 0x9bb1efcf, "mu" },
  [440580] = { "シャーマンの指揮下にあるSpirit Wolvesを2体召喚します。$D1持続します。", nil, 0x1cc2d3c8, nil, "um" },
  [440586] = { "$D1の間、対象をスタンさせます。", "スタンしています。", 0xb330d181, 0x27f95286, "uu" },
  [440589] = { "Spirit Wolvesが遠吠えを上げ、$D1の間、すべての敵に自分たちを攻撃させます。", nil, 0x140cc51b, nil, "um" },
  [440591] = { "すべての移動阻害効果を解除し、$D1の間、自分とSpirit Wolvesの移動速度を$N1%上昇させます。", "移動速度が$N1%上昇します", 0x8027f551, 0xda8c3de1, "uu" },
  [440593] = { "Spirit Wolvesの攻撃が、与えたダメージの$N1%だけ自身とその主人の体力を回復します", "ダメージの$N1%を体力に変換します。", 0x39af52d1, 0x6261a453, "uu" },
  [440605] = { "対象の背後へ跳びます。", nil, 0x17230464, nil, "um" },
  [440609] = { "Spirit Wolvesの攻撃が、与えたダメージの一定割合だけ自身とその主人の体力を回復します。", nil, 0x705e00bc, nil, "um" },
  [440610] = { "すべての移動阻害効果を解除します。", "すべての移動妨害効果に対する免疫があります。", 0xd1a00509, 0x73d23ab8, "uu" },
  [440630] = { "外套にFeral Spiritのルーンを刻みます：\n\n$I1\nシャーマンの指揮下にある二体のSpirit Wolvesを召喚します。効果時間は$D1です。", nil, 0x3a18cf25, nil, "um" },
  [440631] = { "Feral Spiritのアビリティを得ます：\n\n$I1\nシャーマンの指揮下にあるSpirit Wolvesを2体召喚します。$D1持続します。", nil, 0x634dd6c3, nil, "um" },
  [440632] = { "Cat、Bear、Dire Bearフォームでのみ、Attack Powerが+$N1されます。", nil, 0xa798bce2, nil, "um" },
  [440633] = { "Storm, Earth, and Fireのアビリティを得ます：\n\n$I1\nChain Lightningのクールダウンを$N1%短縮し、Earthbind Totemの設置時に対象を$D1の間その場に縛り付け、Flame Shockの継続ダメージを$N3%増加させます。", nil, 0xb7cb4fb1, nil, "um" },
  [440634] = { "外套にStorm, Earth, and Fireのルーンを刻みます：\n\n$I1\nChain Lightningのクールダウンを$N1%短縮し、Earthbind Totemが設置時に対象を$D1の間移動不能にするようになり、Flame Shockの持続ダメージを$N3%増加させます。", nil, 0xb99a4382, nil, "um" },
  [440651] = { "対象はダメージを受けるたびにSacred Shieldを得て、最大$D1の間、$N1のダメージを吸収し、パラディンのFlash of Lightのクリティカル率を$N2%上昇させます。この効果は6秒に一度までしか得られません。$D3持続します。", "ダメージを吸収し、詠唱したパラディンのFlash of Lightのクリティカル率を$N1%上昇させます。", 0x83a78794, 0xc8eb5579, "uu" },
  [440658] = { "盾で対象を殴りつけ、ブロック値に基づくHolyダメージに加えて、さらに$N1のダメージを与えます。", nil, 0x675f9fa9, nil, "um" },
  [440666] = { "Vindicationの才能が発動すると、才能ポイントごとに対象のAttack Powerを$N1低下させ、自分の筋力、敏捷性、Attack Powerを$N2%上昇させるようにもなります。Vindicationの効果時間が$D1に延長されます。", nil, 0x9d03ab96, nil, "um" },
  [440667] = { nil, "Attack Powerが$N1減少します。", nil, 0x3b8db6a5, "mu" },
  [440668] = { nil, "Attack Powerが$N1%増加します。", nil, 0xfe93b3f4, "mu" },
  [440672] = { "JudgementまたはCrusader Strikeがクリティカルになると、対象は$D1かけて追加で$N1%のダメージを受けます。", nil, 0x49f9e1c1, nil, "um" },
  [440675] = { nil, "$D1ごとにHolyダメージを受けます。", nil, 0x74b718e2, "mu" },
  [440720] = { nil, "パラディンになるってこういう感じなのでしょうか？", nil, 0xcab03f05, "mu" },
  [440788] = { "外套にShield of Righteousnessのルーンを刻みます：\n\n$I1\n盾で対象を強打し、ブロック値に基づくHolyダメージに加えて、さらに$N1のダメージを与えます。", nil, 0xb62d614f, nil, "um" },
  [440789] = { "Shield of Righteousnessのアビリティを得ます：\n\n$I1\n盾で対象を打ちつけ、ブロック値に基づくHolyダメージに加えて$N1の追加ダメージを与えます。", nil, 0x60be8165, nil, "um" },
  [440790] = { "外套にShock and Aweのルーンを刻みます：\n\n$I1\nRighteous Furyが有効でない間、Holy Shockでダメージを与えると、知力の$N1%をSpell Damageとして得て、$D1の間、生み出す脅威が$N2%減少します。\n\nInfusion of Lightが刻まれている場合、$D2の間Sunlightを得ます。\n\n$I2\nSunlightにより、Divine Storm、Crusader Strike、およびプレイヤー以外が操作する対象への近接攻撃が、神聖呪文パワーの$N5%に等しい追加のHolyダメージを与えます。", nil, 0x21f37d6a, nil, "um" },
  [440791] = { "Shock and Aweのアビリティを得ます：\n\n$I1\nRighteous Furyが有効でない間、Holy Shockでダメージを与えると、$D1の間、知力の$N1%をSpell Damageとして得て、発生させる脅威が$N2%減少します。\n\nInfusion of Lightを刻んでいる場合、$D2の間Sunlightを得ます。\n\n$I2\nSunlightにより、Divine Storm、Crusader Strike、近接攻撃が、プレイヤー以外が操作する対象に、聖なる呪文力の$N5%に等しいHolyのボーナスダメージを与えるようになります。", nil, 0xeaaff97e, nil, "um" },
  [440792] = { "外套にRighteous Vengeanceのルーンを刻みます：\n\n$I1\nJudgementまたはCrusader Strikeがクリティカルになると、対象は$D1かけて$N1%の追加ダメージを受けます。", nil, 0xdd37e14e, nil, "um" },
  [440794] = { "Righteous Vengeanceのアビリティを得ます：\n\n$I1\nJudgementまたはCrusader Strikeがクリティカルになると、対象は$D1かけて追加で$N1%のダメージを受けます。", nil, 0x582e0479, nil, "um" },
  [440802] = { "渦巻く氷の球を放ちます。球は$D1かけて素早く前進します。移動中、球は$N2秒ごとに、通過したすべての敵に$N3のFrost Damageを与え、移動速度を$N4%低下させるChillを付与します。初めて敵にダメージを与えると、球の動きは遅くなり、100%の確率でFingers of Frostのルーンを発動させます。", nil, 0xcb2a6d8e, nil, "um" },
  [440809] = { nil, "移動速度が$N1%低下しています。", nil, 0x09876d53, "mu" },
  [440820] = { "……", nil, 0x000017b8, nil, "um" },
  [440827] = { "泡立つ大釜に投げ込むと、有毒ガスの爆発を起こします。ステルスは解除されません。", nil, 0x5d2eeb16, nil, "um" },
  [440829] = { "肉と骨の供物を組み合わせます。", nil, 0x49295518, nil, "um" },
  [440830] = { "空の紋章に血の魔法の精髄を込めます。", nil, 0x9ddd6f51, nil, "um" },
  [440841] = { "供物が隠された墓を明らかにします。", "供え物が隠された墓の場所を明らかにします。", 0x4a6817a6, 0x4a6817a6, "uu" },
  [440858] = { "外套にFrozen Orbのルーンを刻みます：\n\n$I1\n渦巻く氷のオーブを放ちます。オーブは$D1かけて素早く前進します。移動中、オーブは$D2ごとに$N3のFrost Damageを与え、通過したすべての敵に移動速度を$N4%低下させるChillを付与します。初めて敵にダメージを与えると、オーブの移動は遅くなり、100%の確率でFingers of Frostのルーンを発動させます。", nil, 0xf8b56c74, nil, "um" },
  [440859] = { "Frozen Orbのアビリティを得ます：\n\n$I1\n渦巻く氷の球を放ちます。球は$D1かけて素早く前進します。移動中、球は$D2ごとに$N3のFrost Damageを与え、通過したすべての敵にChillを付与して移動速度を$N4%低下させます。初めて敵にダメージを与えると球の動きが遅くなり、100%の確率でFingers of Frostのルーンを発動させます。", nil, 0x6788d427, nil, "um" },
  [440870] = { "Soul Fire呪文のクールダウンを$N1%短縮します。体力が$N2%未満の敵にShadow BoltまたはSearing Painを唱えると、その敵が受けるダメージが$N3%増加し、さらに次の$D1の間、Soul Fire呪文の詠唱時間が$N5%短縮され、Soul Shardを消費しなくなります。", nil, 0x7455458a, nil, "um" },
  [440873] = { nil, "Soul Fireの詠唱時間が$N1%短縮され、シャードを消費しません。", nil, 0xf95dd699, "mu" },
  [440882] = { "魂に悪魔のエネルギーが注ぎ込まれ、受けるすべてのMagicダメージを、アーマーによるPhysicalダメージ軽減率の$N1%に等しい割合だけ減少させます。$D1持続します。", "受ける魔法ダメージが$N1%減少します。", 0x8a9f20c0, 0xa6e1df00, "uu" },
  [440892] = { "$D1の間、対象に呪いをかけ、Magic耐性を$N2低下させ、受けるMagicダメージを$N3%増加させます。1体の対象に対して、各ウォーロックがかけられるCurseは1つだけです。", "Magic耐性が$N1低下します。受けるMagicダメージが$N2%増加します。", 0x68afc919, 0x96faf3fe, "uu" },
  [440895] = { nil, "次の単体対象で継続効果のない呪文のクリティカル率が$N1%上昇します。", nil, 0xb7c01d56, "mu" },
  [440922] = { "ブーツにDecimationのルーンを刻みます：\n\n$I1\nSoul Fireのクールダウンを$N1%短縮します。体力が$N2%未満の敵にShadow BoltまたはSearing Painを詠唱すると、与えるダメージが$N3%増加し、次の$D1の間、Soul Fireの詠唱時間が$N5%短縮され、Soul Shardを消費しなくなります。", nil, 0x19ab4ac7, nil, "um" },
  [440923] = { "Decimationのアビリティを得ます：\n\n$I1\nSoul Fireの呪文のクールダウンを$N1%短縮します。体力が$N2%未満の敵にShadow BoltまたはSearing Painを詠唱すると、その敵に与えるダメージが$N3%増加し、次の$D1の間、Soul Fireの呪文の詠唱時間が$N5%短縮され、Soul Shardsを消費しなくなります。", nil, 0x69f5dfca, nil, "um" },
  [440924] = { "外套にMark of Chaosのルーンを刻みます：\n\n$I1\n対象を$D1の間呪い、Magic耐性を$N2減少させ、受けるMagicダメージを$N3%増加させます。一つの対象に対して、ウォーロックごとに有効にできるCurseは一つだけです。", nil, 0x050e05a1, nil, "um" },
  [440925] = { "Mark of Chaosのアビリティを得ます：\n\n$I1\n$D1の間対象に呪いをかけ、Magicの耐性を$N2低下させ、受けるMagicダメージを$N3%増加させます。1体の対象にかけられるCurseは、ウォーロック一人につき一つだけです。", nil, 0xd026046f, nil, "um" },
  [440926] = { "外套にInfernal Armorのルーンを刻みます：\n\n$I1\n魂が悪魔のエネルギーで満たされ、受けるMagicダメージをすべて、アーマーによるPhysicalダメージ軽減率の$N1%に等しい割合だけ軽減します。効果時間は$D1です。", nil, 0x32bd63f1, nil, "um" },
  [440927] = { "Infernal Armorのアビリティを得ます：\n\n$I1\n魂に悪魔のエネルギーが注ぎ込まれ、受けるすべてのMagicダメージを、アーマーによるPhysicalダメージ軽減率の$N1%に等しい割合だけ減少させます。$D1持続します。", nil, 0x1acd9e69, nil, "um" },
  [440981] = { "Weapon Damageが$N1上昇します。", nil, 0xf887b76a, nil, "um" },
})
